      FROM @this_model AS _entity
      WHERE
        _entity._source_row_id IN (
          SELECT
            _source_row_id
          FROM _survivors
        )
    ) AS entity_rows
  FROM _survivors
) AS _conservation
WHERE
  entity_rows + diverted_rows <> surviving_rows
